(6143331, 904777, 104518, '<td valign="top">Apparently not a misquote.</td>', 'Apparently not a misquote.', '2010-08-28 02:28:42.000000', NULL, 1),
(6143333, 905421, 104518, '<td valign="top">Thank you Henry Wadsworth Longfellow. All this time I thought the British were bad guys and then they turn out to be Regulars.</td>', 'Thank you Henry Wadsworth Longfellow. All this time I thought the British were bad guys and then they turn out to be Regulars.', '2010-08-28 02:35:37.000000', NULL, 1),
(6143334, 905317, 104518, '<td valign="top">And if you do it twice, does that make you a so and so?</td>', 'And if you do it twice, does that make you a so and so?', '2010-08-28 02:36:27.000000', NULL, 1),
(6143335, 904656, 104518, '<td valign="top">I can see his point.</td>', 'I can see his point.', '2010-08-28 02:37:37.000000', NULL, 1),
(6143336, 905354, 104518, '<td valign="top">But if we don''t use it to consume beyond our means, won''t we have a double dip recession?</td>', 'But if we don''t use it to consume beyond our means, won''t we have a double dip recession?', '2010-08-28 02:40:20.000000', NULL, 1),
(6143337, 905167, 104518, '<td valign="top">And sometimes it makes it to the camera.</td>', 'And sometimes it makes it to the camera.', '2010-08-28 02:44:16.000000', NULL, 1),
(6143338, 905336, 104518, '<td valign="top">Did you consider using "Death by Chocolate"?</td>', 'Did you consider using "Death by Chocolate"?', '2010-08-28 02:45:45.000000', NULL, 1),
(6143342, 905079, 104518, '<td valign="top">Apparently this has a life of its own, independent of "There is no peace...to the wicked."</td>', 'Apparently this has a life of its own, independent of "There is no peace...to the wicked."', '2010-08-28 02:51:47.000000', NULL, 1),
(6143344, 905302, 104518, '<td valign="top">Actually, this is correct, the other is the misquote.</td>', 'Actually, this is correct, the other is the misquote.', '2010-08-28 02:53:01.000000', NULL, 1),
